<?php

declare(strict_types=1);

namespace App\Hosts;

use App\Attributes\Generation\AutoGenerated;
use App\Bootstrap\Psr4ClassNames;
use App\Console\Support\PintFormatter;
use App\Files\Contracts\Files;
use App\Files\Enums\Place;
use App\Files\Values\Depth;
use App\Hosts\Data\HostProtocolData;
use App\Reflection\Contracts\ReflectorFactory;
use App\Values\FilePath;

/**
 * Compares the files the host protocol generator writes with what protocol/host.json makes of them now, so a change
 * made to the file and not generated, or made to a generated file by hand, is found.
 */
final readonly class HostProtocolCheck
{
    /**
     * The folder every generated PHP class lives under, and the root of every generated Go file.
     */
    private const string PHP_ROOT = 'app/Hosts/Protocol';

    private const string GO_ROOT = 'programs/runner';

    /**
     * The first line of every Go file this generator writes, the form Go tools know a generated file by.
     */
    private const string GO_GENERATED_LINE = '// Code generated by php artisan journal:host-protocol';

    public function __construct(
        private Files $files,
        private PintFormatter $pint,
        private ReflectorFactory $reflectors,
    ) {}

    /**
     * Each generated file's path from the project root, with its source as the protocol file makes it now.
     *
     * @return array<string, string>
     */
    public function sources(): array
    {
        $protocolFile = FilePath::in(Place::Project, HostProtocolSources::PROTOCOL_FILE);

        return new HostProtocolSources(HostProtocolData::from($this->files->readJson($protocolFile)))->sources();
    }

    /**
     * The generated files that differ from what the protocol file makes of them, or are missing, under the folder of
     * the place: the project itself by default.
     *
     * @return list<string>
     */
    public function drifted(Place $place = Place::Project, string $folder = ''): array
    {
        $drifted = [];
        $sources = $this->sources();
        $isPhp = fn (string $relative) => str_ends_with($relative, '.php');

        $expected = [
            ...$sources,
            ...$this->pint->formattedAll(array_filter($sources, $isPhp, ARRAY_FILTER_USE_KEY)),
        ];

        foreach ($expected as $relative => $source) {
            $target = FilePath::in($place, ltrim("{$folder}/{$relative}", '/'));

            if (! $this->files->exists($target) || $source !== $this->files->read($target)) {
                $drifted[] = $relative;
            }
        }

        $leftOver = array_diff($this->generatedFiles($place, $folder), array_keys($sources));

        return [
            ...$drifted,
            ...array_values($leftOver),
        ];
    }

    /**
     * Every file this generator made before, deleted before a run writes anew: each PHP class carrying #[AutoGenerated]
     * of the protocol file, found by reflection, and each Go file under the Go roots that opens with the standard first
     * line Go tools know a generated file by.
     *
     * @return list<string>
     */
    public function generatedFiles(Place $place = Place::Project, string $folder = ''): array
    {
        return [
            ...$this->generatedClasses($place, $folder),
            ...$this->generatedGoFiles($place, $folder),
        ];
    }

    /**
     * @return list<string>
     */
    private function generatedClasses(Place $place, string $folder): array
    {
        $names = Psr4ClassNames::fromComposer();
        $generated = [];

        foreach ($this->listed($place, $folder, self::PHP_ROOT, '*.php') as $path) {
            // The class is the project's own of that path, wherever the files under check were written; a copy whose class
            // the project no longer has is a file an earlier run of the generator wrote there.
            $projectFile = FilePath::in(Place::Project, $path);
            $isGenerated = ! $this->files->exists($projectFile) || $this->carriesMark($names->classOf(base_path($path)));

            if ($isGenerated) {
                $generated[] = $path;
            }
        }

        return $generated;
    }

    /**
     * Whether the class carries #[AutoGenerated] of the protocol file.
     *
     * @param  class-string  $class
     */
    private function carriesMark(string $class): bool
    {
        $reflected = $this->reflectors->make($class);

        return $reflected->hasAttribute(AutoGenerated::class)
            && $reflected->attribute(AutoGenerated::class)->source === HostProtocolSources::PROTOCOL_FILE;
    }

    /**
     * @return list<string>
     */
    private function generatedGoFiles(Place $place, string $folder): array
    {
        return array_values(array_filter(
            $this->listed($place, $folder, self::GO_ROOT, '*.go'),
            fn (string $path) => str_starts_with(
                $this->files->read(FilePath::in($place, ltrim("{$folder}/{$path}", '/'))),
                self::GO_GENERATED_LINE,
            ),
        ));
    }

    /**
     * The files of the pattern under the root and below it, each by its path from the project root.
     *
     * @return list<string>
     */
    private function listed(Place $place, string $folder, string $root, string $pattern): array
    {
        $rootFolder = FilePath::in($place, ltrim("{$folder}/{$root}", '/'));

        // A folder the generator never wrote to, as a check's own folder before its first run, holds nothing of it.
        if (! $this->files->exists($rootFolder)) {
            return [];
        }

        $listed = $this->files->list($rootFolder, Depth::levels(6), $pattern);

        return array_map(
            fn (FilePath $path) => ltrim(substr($path->relative, strlen($folder)), '/'),
            $listed->paths(),
        );
    }
}
